// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/applications", wrapper.ListMyApplications)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/applications", wrapper.CreateApplication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/applications/{applicationId}", wrapper.GetMyApplication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/applications/{applicationId}/history", wrapper.GetMyApplicationHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/applications/{applicationId}/withdraw", wrapper.WithdrawApplication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/applications/{applicationId}", wrapper.GetHrApplication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/applications/{applicationId}/history", wrapper.GetHrApplicationHistory)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/hr/applications/{applicationId}/status", wrapper.ChangeApplicationStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/companies/{companyId}/analytics/dynamics", wrapper.GetCompanyDynamics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/companies/{companyId}/analytics/summary", wrapper.GetCompanyAnalyticsSummary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/companies/{companyId}/applications", wrapper.ListCompanyApplications)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/vacancies/{vacancyId}/analytics/dynamics", wrapper.GetVacancyDynamics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/vacancies/{vacancyId}/analytics/summary", wrapper.GetVacancyAnalyticsSummary)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/hr/vacancies/{vacancyId}/applications", wrapper.ListVacancyApplications)
	})

	return r
}

